func TestRFC3339NanoMax(t *testing.T) {
	t.Run("returns the input when before the max", func(t *testing.T) {
		in := time.Date(2024, time.June, 15, 12, 0, 0, 500000000, time.UTC)
		require.Equal(t, in, timex.RFC3339NanoMax(in))
	})

	t.Run("returns the input when equal to the max", func(t *testing.T) {
		in := timex.RFC3339Inf()
		require.Equal(t, in, timex.RFC3339NanoMax(in))
	})

	t.Run("returns the max when input is after the max", func(t *testing.T) {
		in := timex.Inf()
		require.Equal(t, timex.RFC3339Inf(), timex.RFC3339NanoMax(in))
	})

	t.Run("returns the input one nanosecond before the max", func(t *testing.T) {
		in := timex.RFC3339Inf().Add(-time.Nanosecond)
		require.Equal(t, in, timex.RFC3339NanoMax(in))
	})
}
